UPDATE runtime_delivery_units SET status='rejected',updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE operation_id=?1 AND attempt=?2 AND ordinal=0 AND status='sending' AND NOT EXISTS(SELECT 1 FROM runtime_delivery_units other WHERE other.operation_id=?1 AND other.attempt=?2 AND other.status IN ('sending','unknown') AND other.ordinal<>0) AND EXISTS(SELECT 1 FROM runtime_operations op WHERE op.id=?1 AND op.attempt=?2 AND op.lease_token=?3 AND op.worker_id=?4 AND op.status='delivering' AND op.lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND op.cancel_requested=0 AND op.cache_bypassed=0 AND op.delivered_artifact_count=0 AND CAST(json_extract(op.request,'$.actor_id') AS TEXT)=CAST(op.actor_id AS TEXT) AND CAST(json_extract(op.request,'$.target.bot_id') AS TEXT)=CAST(?7 AS TEXT) AND op.cache_key=?5 AND NOT EXISTS(SELECT 1 FROM runtime_delivery_units du WHERE du.operation_id=op.id AND du.attempt=op.attempt AND du.status='sent'));